        public static bool ExtractResourcesByName(ResourceManager theManager, string theName, bool unpackAtlases = true)
        {
            switch (theName)
            {
            case "LoadCommon":
                return ExtractLoadCommonResources(theManager, unpackAtlases);
            case "Load":
                return ExtractLoadResources(theManager, unpackAtlases);
            case "LoadNights":
                return ExtractLoadNightsResources(theManager, unpackAtlases);
            case "LoadingThread":
                return ExtractLoadingThreadResources(theManager, unpackAtlases);
            case "CharSelect":
                return ExtractCharSelectResources(theManager, unpackAtlases);
            case "CharInGame":
                return ExtractCharInGameResources(theManager, unpackAtlases);
            case "IP":
                return ExtractIPResources(theManager, unpackAtlases);
            case "IP_1":
