            case "IP_8":
                return ExtractIP_8Resources(theManager, unpackAtlases);
            case "IP_9":
                return ExtractIP_9Resources(theManager, unpackAtlases);
            case "IP_10":
                return ExtractIP_10Resources(theManager, unpackAtlases);
            case "MainMenuCommon":
                return ExtractMainMenuCommonResources(theManager, unpackAtlases);
            case "MainMenuPeggle":
                return ExtractMainMenuPeggleResources(theManager, unpackAtlases);
            case "MainMenuNights":
                return ExtractMainMenuNightsResources(theManager, unpackAtlases);
            case "LevelSelect":
                return ExtractLevelSelectResources(theManager, unpackAtlases);
            case "Help":
                return ExtractHelpResources(theManager, unpackAtlases);
            case "Game":
                return ExtractGameResources(theManager, unpackAtlases);
            case "Fever":
                return ExtractFeverResources(theManager, unpackAtlases);
            case "TrophyRoom":
                return ExtractTrophyRoomResources(theManager, unpackAtlases);
            case "TrophyRoomNights":
                return ExtractTrophyRoomNightsResources(theManager, unpackAtlases);
            case "Dialog":
                return ExtractDialogResources(theManager, unpackAtlases);
