        private static Dictionary<string, ResourceId> sStringToId;

        public static string GetStringIdById(ResourceId theId)
        {
            return (int)theId >= 0 && (int)theId < sResourceIdNames.Length ? sResourceIdNames[(int)theId] : "";
        }

        public static ResourceId GetIdByStringId(string theStringId)
        {
            if (sStringToId == null)
            {
                sStringToId = new Dictionary<string, ResourceId>();
                for (int i = 0; i < sResourceIdNames.Length; i++)
                {
                    sStringToId[sResourceIdNames[i]] = (ResourceId)i;
                }
            }
            return sStringToId.TryGetValue(theStringId, out ResourceId id) ? id : ResourceId.RESOURCE_ID_MAX;
        }

